from pathlib import Path
import json,gzip,hashlib,numpy as np
root=Path.cwd();d=root/'learnings/policy_tuning/RobotLab-Isaac-BeyondMimic-Flat-LW-wheel-v0/2026-11-07_15-01-47/evaluations/wheel-to-leg-fixed-start-20261108-001'
ref=lambda p:{'path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
out={'version':1,'source':CODE_SOURCE,'inputs':[],'cases':{}}
for case in ['nominal','randomized']:
 p=d/'raw'/f'fixed-start-{case}-a01/telemetry.json.gz'
 with gzip.open(p,'rt') as f:t=json.load(f)
 out['inputs'].append(ref(p));j=[i for i,n in enumerate(t['joint_names']) if 'wheel' in n];ps=t['physics_samples'];acc=np.array([x['joint_acceleration'] for x in ps])[:,j];last=np.array([x['substep']==3 for x in ps]);im,jj=np.unravel_index(np.abs(acc).argmax(),acc.shape);s=ps[im]
 out['cases'][case]={'acceleration_peak_all_substeps_rad_s2':float(abs(acc).max()),'acceleration_peak_last_substeps_rad_s2':float(abs(acc[last]).max()),'peak_substep_zero_based':s['substep'],'peak_time_s':s['frame_index']/50+(s['substep']+1)*.005,'peak_joint':t['joint_names'][j[jj]],'peak_episode':s['episode_id']}
out['interpretation']='The reward reads asset.data.joint_acc once at each control-step boundary; it does not aggregate all four physics-substep peaks. Absence from the final-substep sample does not mean an impact has no later effect on rewards.'
with (d/'derived/sampling-audit.json').open('x') as f:json.dump(out,f,indent=2,allow_nan=False)
print(json.dumps(out['cases']))
